#!/usr/bin/env python3
from pathlib import Path
import json,re,sys
root=Path(__file__).resolve().parents[2]
catalog=json.loads((root/'Source/Translations.json').read_text(encoding="utf-8"))
def literal(s):return 'u8'+json.dumps(s,ensure_ascii=False)
header='// Generated by .github/checks/localisation_catalog.py. Edit Translations.json.\n#pragma once\nnamespace flowui { struct Translation { const char* ru; const char* en; };\ninline constexpr Translation translations[] = {\n'
for source,target in catalog.items():
    assert target and not re.search('[А-Яа-яЁё]',target),source
    header+='    { '+literal(source)+', '+literal(target)+' },\n'
header+='}; }\n'
path=root/'Source/LocalisationStrings.h'
if '--check' in sys.argv:
    assert path.read_text(encoding="utf-8")==header,'Generated catalog is stale'
    missing=[]
    for source in (root/'Source').iterdir():
        if source.suffix not in ['.h','.cpp','.mm'] or source.name in ['LocalisationStrings.h','Localisation.h']:continue
        for match in re.finditer(r'u8"(?:[^"\\]|\\.)*"(?:\s*u8"(?:[^"\\]|\\.)*")*',source.read_text(encoding="utf-8")):
            value=''.join(json.loads(s[2:]) for s in re.findall(r'u8"(?:[^"\\]|\\.)*"',match.group()))
            if re.search('[А-Яа-яЁё]',value) and value not in catalog:missing.append((source.name,value))
    assert not missing,missing
    print(str(len(catalog))+' translations: coverage and generated header PASS')
else:path.write_text(header,encoding="utf-8")
